// 取某词的近反义词条目（{t: 表记, y: 读音}）
export function wordRelationsOf(id) {
  const r = wordRelations[id]
  if (!r) return { syn: [], ant: [] }
  const norm = arr => (arr || []).map(x => ({ t: x[0], y: x[1] || '' }))
  return { syn: norm(r.syn), ant: norm(r.ant) }
}
